using AzdoQualityMetrics.Config;
using AzdoQualityMetrics.Interfaces;
using AzdoQualityMetrics.Models;
using Microsoft.Extensions.Logging;
using System.Net;
using System.Net.Http.Headers;
using System.Text;
using System.Text.Json;

namespace AzdoQualityMetrics.AzureDevOps;
public sealed class AzureDevOpsClient : IAzureDevOpsClient
{
 private readonly IConfigurationService _config; private readonly ILogger<AzureDevOpsClient> _logger; private readonly HttpClient _http=new(); private readonly SemaphoreSlim _gate=new(6,6); private const string Api="7.1";
 public AzureDevOpsClient(IConfigurationService config,ILogger<AzureDevOpsClient> logger){_config=config;_logger=logger;}
 private string Base => $"https://dev.azure.com/{Uri.EscapeDataString(_config.Settings.Organization)}/{Uri.EscapeDataString(_config.Settings.Project)}/_apis";
 private void Authorize(){if(string.IsNullOrWhiteSpace(_config.Settings.Pat)) throw new InvalidOperationException("No personal access token is configured in appsettings.json."); var token=Convert.ToBase64String(Encoding.ASCII.GetBytes(":"+_config.Settings.Pat));_http.DefaultRequestHeaders.Authorization=new AuthenticationHeaderValue("Basic",token);}
 private async Task<JsonDocument> GetJsonAsync(string url,CancellationToken ct){await _gate.WaitAsync(ct);try{Authorize();using var response=await _http.GetAsync(url,ct);if(response.StatusCode==HttpStatusCode.TooManyRequests)throw new HttpRequestException("Azure DevOps rate limit reached (429).");response.EnsureSuccessStatusCode();return JsonDocument.Parse(await response.Content.ReadAsStringAsync(ct));}finally{_gate.Release();}}
 public async Task<bool> ConnectAsync(CancellationToken ct){using var d=await GetJsonAsync($"https://dev.azure.com/{Uri.EscapeDataString(_config.Settings.Organization)}/_apis/projects/{Uri.EscapeDataString(_config.Settings.Project)}?api-version={Api}",ct);return d.RootElement.TryGetProperty("id",out _);}
 public async Task<IReadOnlyList<AreaNode>> GetAreasAsync(CancellationToken ct){using var d=await GetJsonAsync($"{Base}/wit/classificationnodes/Areas?$depth=20&api-version={Api}",ct);var roots=new List<AreaNode>();if(d.RootElement.TryGetProperty("children",out var children))foreach(var c in children.EnumerateArray())roots.Add(ParseArea(c));return roots;}
 private static AreaNode ParseArea(JsonElement e){var n=new AreaNode{Id=e.TryGetProperty("id",out var id)?id.GetInt32():0,Name=e.GetProperty("name").GetString()??"",Path=e.TryGetProperty("path",out var p)?p.GetString()??"":""};if(e.TryGetProperty("children",out var ch))foreach(var x in ch.EnumerateArray()){var child=ParseArea(x);child.Parent=n;n.Children.Add(child);}return n;}
 public async Task<IReadOnlyList<WorkItemDefinition>> GetWorkItemTypesAsync(CancellationToken ct){using var d=await GetJsonAsync($"{Base}/wit/workitemtypes?api-version={Api}",ct);return d.RootElement.GetProperty("value").EnumerateArray().Select(x=>new WorkItemDefinition(x.GetProperty("name").GetString()??"")).ToList();}
 public async Task<IReadOnlyList<StateDefinition>> GetStatesAsync(CancellationToken ct){using var d=await GetJsonAsync($"{Base}/wit/workitemtypes?api-version={Api}",ct);var list=new List<StateDefinition>();foreach(var t in d.RootElement.GetProperty("value").EnumerateArray()){var name=t.GetProperty("name").GetString()??"";try{using var states=await GetJsonAsync($"{Base}/wit/workitemtypes/{Uri.EscapeDataString(name)}/states?api-version={Api}",ct);foreach(var s in states.RootElement.GetProperty("value").EnumerateArray()){var sn=s.GetProperty("name").GetString()??"";var cat=s.TryGetProperty("category",out var catEl)?catEl.GetString()??"":"";if(!list.Any(x=>x.Name==sn))list.Add(new StateDefinition(sn,cat));}}catch(Exception ex){_logger.LogWarning(ex,"Could not load states for {Type}",name);}}return list;}
 public async Task<IReadOnlyList<int>> QueryWorkItemIdsAsync(CalculationRequest r,bool bugs,CancellationToken ct){var typeClause=bugs?"[System.WorkItemType] = 'Bug'":"("+string.Join(" OR ",r.WorkItemTypes.Select(t=>$"[System.WorkItemType] = '{t.Replace("'","''")}'"))+")";var clauses=new List<string>{$"[System.TeamProject] = @project",typeClause};if(bugs){clauses.Add($"[System.CreatedDate] >= '{r.StartDate:yyyy-MM-dd}'");clauses.Add($"[System.CreatedDate] < '{r.EndDate.Date.AddDays(1):yyyy-MM-dd}'");}else if(r.WorkItemTypes.Count==0)return Array.Empty<int>();if(r.AreaPaths.Count>0)clauses.Add("("+string.Join(" OR ",r.AreaPaths.Select(p=>$"[System.AreaPath] UNDER '{p.Replace("'","''")}'"))+")");var wiql="SELECT [System.Id] FROM WorkItems WHERE "+string.Join(" AND ",clauses);var body=JsonSerializer.Serialize(new{query=wiql});using var content=new StringContent(body,Encoding.UTF8,"application/json");Authorize();using var response=await _http.PostAsync($"{Base}/wit/wiql?api-version={Api}",content,ct);response.EnsureSuccessStatusCode();using var d=JsonDocument.Parse(await response.Content.ReadAsStringAsync(ct));return d.RootElement.GetProperty("workItems").EnumerateArray().Select(x=>x.GetProperty("id").GetInt32()).ToList();}
 public async Task<IReadOnlyList<WorkItemRecord>> GetWorkItemsAsync(IReadOnlyList<int> ids,CancellationToken ct){var result=new List<WorkItemRecord>();foreach(var batch in ids.Chunk(200)){ct.ThrowIfCancellationRequested();var url=$"{Base}/wit/workitems?ids={string.Join(",",batch)}&fields=System.Id,System.Title,System.CreatedDate,System.AreaPath,System.WorkItemType,Microsoft.VSTS.Scheduling.Effort&api-version={Api}";using var d=await GetJsonAsync(url,ct);foreach(var e in d.RootElement.GetProperty("value").EnumerateArray()){var f=e.GetProperty("fields");double? effort=f.TryGetProperty("Microsoft.VSTS.Scheduling.Effort",out var ef)&&ef.ValueKind==JsonValueKind.Number?ef.GetDouble():null;result.Add(new WorkItemRecord{Id=e.GetProperty("id").GetInt32(),Title=f.TryGetProperty("System.Title",out var title)?title.GetString()??"":"",CreatedDate=f.TryGetProperty("System.CreatedDate",out var cd)?cd.GetDateTime():null,AreaPath=f.TryGetProperty("System.AreaPath",out var ap)?ap.GetString()??"":"",WorkItemType=f.TryGetProperty("System.WorkItemType",out var wt)?wt.GetString()??"":"",Effort=effort});}}return result;}
 public async Task<IReadOnlyList<WorkItemUpdate>> GetUpdatesAsync(int id,CancellationToken ct){using var d=await GetJsonAsync($"{Base}/wit/workitems/{id}/updates?api-version={Api}",ct);var list=new List<WorkItemUpdate>();foreach(var u in d.RootElement.GetProperty("value").EnumerateArray()){if(!u.TryGetProperty("fields",out var fields)||!fields.TryGetProperty("System.State",out var state))continue;var changed=u.TryGetProperty("revisedDate",out var date)?date.GetDateTime():DateTime.MinValue;var old=state.TryGetProperty("oldValue",out var ov)?ov.GetString():null;var next=state.TryGetProperty("newValue",out var nv)?nv.GetString():null;list.Add(new WorkItemUpdate(id,changed,old,next));}return list;}
}
